<script setup lang="ts">
import TermText from './TermText.vue'
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { answerAtlasQuestion, atlasDefaults, atlasQuestions, atlasQuestionsEn, atlasRecords, atlasRecordsEn, buildComparison, countUnitLabels, countUnitLabelsEn, recordFor, recordsForSpecies, speciesOptions } from '../learning/speciesAtlas'
import { BASE, withBase } from '../siteBase'
import { L, localeTag, useMessages } from '../i18n'
import { messages } from './SpeciesAtlasPage.messages'

const emit = defineEmits<{ ready: [] }>()
const m = useMessages(messages)
const species = ref<Parameters<typeof recordsForSpecies>[0]>(atlasDefaults.species)
const selectedRecordId = ref<string>(atlasDefaults.selectedRecordId)
const comparisonLeftId = ref<string>(atlasDefaults.comparisonLeftId)
const comparisonRightId = ref<string>(atlasDefaults.comparisonRightId)
const answers = ref<Record<string, string>>({})
// The status line is kept as a function, and names its record by id, so it follows a language change.
const status = ref<(() => string) | null>(null)
// Records, questions and comparisons are read in the current language; selections are ids.
const records = computed(() => L(atlasRecords, atlasRecordsEn))
const questions = computed(() => L(atlasQuestions, atlasQuestionsEn))
const filteredRecords = computed(() => recordsForSpecies(species.value))
const selected = computed(() => recordFor(selectedRecordId.value))
const comparison = computed(() => buildComparison(comparisonLeftId.value, comparisonRightId.value))
const answeredCount = computed(() => Object.keys(answers.value).length)
const countText = (value: number | null, approximate: boolean) => value === null ? m.value.notGiven : `${approximate ? '≈ ' : ''}${value.toLocaleString(localeTag())}`
const unitLabel = (unit: string) => (L(countUnitLabels, countUnitLabelsEn) as Readonly<Record<string, string>>)[unit] ?? unit
const licenseLabel = (record: typeof selected.value) => record.license.status === 'verified' ? m.value.licenseVerified(record.license.name) : m.value.licenseUnverified
const answerFor = (questionId: string) => answerAtlasQuestion(questionId, answers.value[questionId]!)
watch(species, () => {
  if (!filteredRecords.value.some(record => record.id === selectedRecordId.value)) selectedRecordId.value = filteredRecords.value[0]!.id
  const count = filteredRecords.value.length
  const id = selectedRecordId.value
  status.value = () => m.value.statusShown(count, recordFor(id).shortTitle)
}, { flush: 'sync' })
watch(selectedRecordId, id => { status.value = () => m.value.statusSelected(recordFor(id).shortTitle) }, { flush: 'sync' })
function resetAtlas() {
  species.value = atlasDefaults.species
  selectedRecordId.value = atlasDefaults.selectedRecordId
  comparisonLeftId.value = atlasDefaults.comparisonLeftId
  comparisonRightId.value = atlasDefaults.comparisonRightId
  answers.value = {}
  status.value = () => m.value.statusReset
}
onMounted(async () => { await nextTick(); emit('ready') })
</script>

<template>
  <main id="species-atlas" tabindex="-1" class="atlas-page" data-catalog-kind="static-reference">
    <header class="atlas-intro"><div><p class="atlas-eyebrow">{{ m.eyebrow }}</p><h1 id="atlas-title" tabindex="-1">{{ m.titleLead }} <em>{{ m.titleEmphasis }}</em></h1><p class="atlas-summary">{{ m.summary }}</p><p class="atlas-meta">{{ m.meta }}</p></div><button type="button" class="atlas-reset" @click="resetAtlas">{{ m.reset }}</button></header>
    <div class="atlas-boundary"><strong>{{ m.boundaryLead }}</strong><p>{{ m.boundary }}</p></div>
    <nav class="atlas-navigation" :aria-label="m.navigation"><a href="#atlas-records">{{ m.navRecords }}</a><a href="#atlas-comparison">{{ m.navComparison }}</a><a href="#atlas-scope-quiz">{{ m.navQuiz }}</a><a href="#atlas-interpretation">{{ m.navInterpretation }}</a><a href="#atlas-sources">{{ m.navSources }}</a></nav>

    <section id="atlas-records" tabindex="-1" aria-labelledby="atlas-records-title" class="atlas-section">
      <p class="atlas-eyebrow">{{ m.recordsEyebrow }}</p><h2 id="atlas-records-title">{{ m.recordsTitle }}</h2><p class="atlas-paragraph">{{ m.recordsIntro }}</p>
      <div class="atlas-workspace"><div class="atlas-controls"><h3>{{ m.controlsTitle }}</h3><label for="atlas-species-filter">{{ m.speciesFilter }}</label><select id="atlas-species-filter" v-model="species"><option value="all">{{ m.allSpecies }}</option><option v-for="option in speciesOptions" :key="option.id" :value="option.id">{{ option.label }}</option></select><label for="atlas-record-select">{{ m.catalogRecord }}</label><select id="atlas-record-select" v-model="selectedRecordId"><option v-for="record in filteredRecords" :key="record.id" :value="record.id">{{ record.shortTitle }}</option></select><p>{{ m.filterNote }}</p><p>{{ m.notGivenNote }}</p><p data-testid="atlas-selection-status" role="status" aria-live="polite" aria-atomic="true" class="atlas-status">{{ status?.() }}</p></div>
        <article data-testid="atlas-selected-record" :data-record-id="selected.id" :data-species-id="selected.speciesId" :data-model-status="selected.modelStatus.kind" :data-record-kind="selected.kind" :data-circuitiary-relation="selected.circuitiaryRelation.kind" class="atlas-record"><span class="atlas-record-tag">{{ selected.kind === 'current-subset' ? m.tagCurrentSubset : m.tagPublished }}</span><h3><TermText :text="selected.title" /></h3><p class="atlas-record-summary"><TermText :text="selected.circuitiaryRelation.label" />. <TermText :text="selected.circuitiaryRelation.note" /></p>
          <dl class="atlas-facts"><div data-field="species"><dt>{{ m.species }}</dt><dd><TermText :text="speciesOptions.find(option => option.id === selected.speciesId)?.label" /></dd></div><div data-field="stage"><dt>{{ m.stage }}</dt><dd><TermText :text="selected.stage.label" /></dd></div><div data-field="sex"><dt>{{ m.sex }}</dt><dd><TermText :text="selected.sex.label" /></dd></div><div data-field="scope"><dt>{{ m.region }}</dt><dd><TermText :text="selected.scope.label" /><p><TermText :text="selected.scope.region" /></p></dd></div><div data-field="reconstruction"><dt>{{ m.reconstruction }}</dt><dd><TermText :text="selected.reconstruction.label" /><p><TermText :text="selected.reconstruction.note" /></p></dd></div><div data-field="version"><dt>{{ m.versionOrPublication }}</dt><dd><TermText :text="selected.version.label" /><p>{{ m.pinnedRecord }}: <code>{{ selected.version.pinned }}</code></p></dd></div><div data-field="counts"><dt>{{ m.counts }}</dt><dd><ul class="atlas-counts"><li v-for="count in selected.counts" :key="count.kind" :data-count-kind="count.kind" :data-value="count.value ?? 'not-reported'" :data-unit="count.unit" :data-approximate="count.approximate"><span><TermText :text="count.label" />: </span><strong>{{ countText(count.value, count.approximate) }}</strong><span> · <TermText :text="unitLabel(count.unit)" /></span><p><TermText :text="count.definition" /></p></li></ul></dd></div><div data-field="chemical-coverage"><dt>{{ m.chemicalCoverage }}</dt><dd><TermText :text="selected.chemicalCoverage" /></dd></div><div data-field="gap-coverage"><dt>{{ m.electricalCoverage }}</dt><dd><TermText :text="selected.gapCoverage" /></dd></div><div data-field="model-status"><dt>{{ m.modelStatus }}</dt><dd><TermText :text="selected.modelStatus.label" /></dd></div><div data-field="access"><dt>{{ m.access }}</dt><dd><a :href="selected.access.url" rel="noopener">{{ selected.access.label }} ↗</a><p><TermText :text="selected.access.note" /></p></dd></div><div data-field="license" :data-license-status="selected.license.status"><dt>{{ m.dataLicense }}</dt><dd><TermText :text="licenseLabel(selected)" /><p><TermText :text="selected.license.note" /></p><a v-if="selected.license.sourceUrl" :href="selected.license.sourceUrl" rel="noopener">{{ m.readLicenseSource }}</a></dd></div><div data-field="checked-date"><dt>{{ m.checkedDate }}</dt><dd><TermText :text="selected.checkedDate" /></dd></div></dl>
          <div class="atlas-limitations"><h4>{{ m.limitations }}</h4><ul><li v-for="limitation in selected.limitations" :key="limitation"><TermText :text="limitation" /></li></ul></div><ul class="atlas-primary-links" :aria-label="m.primarySources"><li v-for="source in selected.sources" :key="source.id"><a :href="source.url" rel="noopener">{{ source.title }} <span aria-hidden="true">↗</span></a></li></ul>
        </article>
      </div>
    </section>

    <section id="atlas-comparison" tabindex="-1" aria-labelledby="atlas-comparison-title" class="atlas-section">
      <p class="atlas-eyebrow">{{ m.comparisonEyebrow }}</p><h2 id="atlas-comparison-title">{{ m.comparisonTitle }}</h2><p class="atlas-paragraph"><TermText :text="m.comparisonIntro" /></p>
      <div class="atlas-comparison-selectors"><div><label for="atlas-compare-a">{{ m.comparisonA }}</label><select id="atlas-compare-a" v-model="comparisonLeftId"><option v-for="record in records" :key="record.id" :value="record.id">{{ record.shortTitle }}</option></select></div><div><label for="atlas-compare-b">{{ m.comparisonB }}</label><select id="atlas-compare-b" v-model="comparisonRightId"><option v-for="record in records" :key="record.id" :value="record.id">{{ record.shortTitle }}</option></select></div></div>
      <div data-testid="atlas-comparison" :data-left-id="comparison.left.id" :data-right-id="comparison.right.id" :data-same-record="comparison.sameRecord"><p v-if="comparison.sameRecord" data-testid="atlas-same-record" role="status" class="atlas-comparison-note">{{ m.sameRecordNote }}</p><p v-else class="atlas-comparison-note">{{ m.comparisonNote }}</p>
        <table class="atlas-comparison-table"><caption>{{ comparison.left.shortTitle }} / {{ comparison.right.shortTitle }}</caption><thead><tr><th scope="col">{{ m.property }}</th><th scope="col">A · <TermText :text="comparison.left.shortTitle" /></th><th scope="col">B · <TermText :text="comparison.right.shortTitle" /></th></tr></thead><tbody><tr v-for="row in comparison.rows" :key="row.key" :data-comparison-row="row.key" :data-different="row.different"><th scope="row"><TermText :text="row.label" /></th><td><TermText :text="row.left" /></td><td><TermText :text="row.right" /></td></tr><template v-for="row in comparison.countRows" :key="row.kind"><tr :data-count-comparison="row.kind" :data-classification="row.classification"><th scope="row"><TermText :text="row.label" /></th><td data-side="left" :data-value="row.leftMetric?.value ?? 'not-reported'" :data-unit="row.leftMetric?.unit ?? 'not-reported'"><template v-if="row.leftMetric"><p><strong>{{ countText(row.leftMetric.value, row.leftMetric.approximate) }}</strong> · <TermText :text="unitLabel(row.leftMetric.unit)" /></p><p><TermText :text="row.leftMetric.definition" /></p></template><span v-else>{{ m.notGiven }}</span></td><td data-side="right" :data-value="row.rightMetric?.value ?? 'not-reported'" :data-unit="row.rightMetric?.unit ?? 'not-reported'"><template v-if="row.rightMetric"><p><strong>{{ countText(row.rightMetric.value, row.rightMetric.approximate) }}</strong> · <TermText :text="unitLabel(row.rightMetric.unit)" /></p><p><TermText :text="row.rightMetric.definition" /></p></template><span v-else>{{ m.notGiven }}</span></td></tr><tr class="atlas-unit-note"><td colspan="3"><TermText :text="row.note" /></td></tr></template></tbody></table>
      </div>
    </section>

    <section id="atlas-scope-quiz" tabindex="-1" aria-labelledby="atlas-scope-quiz-title" class="atlas-section"><p class="atlas-eyebrow">{{ m.quizEyebrow }}</p><h2 id="atlas-scope-quiz-title">{{ m.quizTitle }}</h2><p class="atlas-paragraph">{{ m.quizIntro }}</p><p class="atlas-control-note" data-testid="atlas-quiz-progress">{{ m.quizProgress(answeredCount, questions.length) }}</p><div class="atlas-quiz-grid"><fieldset v-for="(question, index) in questions" :key="question.id" :data-question-id="question.id" class="atlas-question"><legend><TermText :text="index + 1" />. <TermText :text="question.prompt" /></legend><label v-for="option in question.options" :key="option.id" :for="`atlas-answer-${question.id}-${option.id}`"><input :id="`atlas-answer-${question.id}-${option.id}`" v-model="answers[question.id]" type="radio" :name="`atlas-question-${question.id}`" :value="option.id" :aria-describedby="`atlas-feedback-${question.id}`" /><span>{{ option.label }}</span></label><div :id="`atlas-feedback-${question.id}`" :data-testid="`atlas-quiz-feedback-${question.id}`" role="status" aria-live="polite" aria-atomic="true" :data-correct="answers[question.id] ? answerFor(question.id).correct : undefined"><div v-if="answers[question.id]" class="atlas-question-feedback"><strong>{{ answerFor(question.id).correct ? m.correct : m.incorrect }}</strong><p>{{ answerFor(question.id).explanation }}</p></div><p v-else class="atlas-question-prompt">{{ m.feedbackPrompt }}</p></div></fieldset></div></section>

    <section id="atlas-interpretation" tabindex="-1" aria-labelledby="atlas-interpretation-title" class="atlas-section"><p class="atlas-eyebrow">{{ m.interpretationEyebrow }}</p><h2 id="atlas-interpretation-title">{{ m.interpretationTitle }}</h2><p class="atlas-paragraph"><TermText :text="m.interpretationIntro" /></p><ol class="atlas-evidence-layers"><li><span>01</span><h3>{{ m.layerMapTitle }}</h3><p>{{ m.layerMap }}</p></li><li><span>02</span><h3>{{ m.layerModelTitle }}</h3><p><TermText :text="m.layerModel" /></p></li><li><span>03</span><h3>{{ m.layerBehaviorTitle }}</h3><p>{{ m.layerBehavior }}</p></li><li><span>04</span><h3>{{ m.layerValidationTitle }}</h3><p>{{ m.layerValidation }}</p></li></ol><p class="atlas-paragraph"><TermText :text="m.scopeCaution" /></p><p class="atlas-paragraph">{{ m.currentModel }}</p></section>

    <section id="atlas-sources" tabindex="-1" aria-labelledby="atlas-sources-title" class="atlas-section"><p class="atlas-eyebrow">{{ m.sourcesEyebrow }}</p><h2 id="atlas-sources-title">{{ m.sourcesTitle }}</h2><p class="atlas-paragraph">{{ m.sourcesIntro }}</p><div class="atlas-source-cards"><article v-for="record in records" :key="record.id" :data-source-record-id="record.id"><h3><TermText :text="record.shortTitle" /></h3><p><TermText :text="record.scope.label" /> · <TermText :text="record.stage.label" /> · <TermText :text="record.sex.label" /></p><p>{{ m.version }}: <TermText :text="record.version.label" />.</p><p>{{ m.pinnedRecord }}: <code>{{ record.version.pinned }}</code></p><p :data-license-status="record.license.status">{{ m.dataLicense }}: <TermText :text="licenseLabel(record)" />.</p><p><TermText :text="record.license.note" /></p><p>{{ m.checkedDate }}: <TermText :text="record.checkedDate" />.</p><ul><li v-for="source in record.sources" :key="source.id"><a :href="source.url" rel="noopener">{{ source.title }} <span aria-hidden="true">↗</span></a></li><li v-if="record.license.sourceUrl"><a :href="record.license.sourceUrl" rel="noopener">{{ m.licenseSource }} <span aria-hidden="true">↗</span></a></li></ul></article></div><p class="atlas-paragraph" data-testid="atlas-additional-context"><TermText :text="m.additionalContext" /><a href="https://www.nature.com/articles/s41586-026-10735-w" rel="noopener">{{ m.bancStudy }}</a></p><p class="atlas-paragraph">{{ m.noDownload }}</p></section>
    <div class="atlas-next"><a :href="withBase('/ogren/gercek-veri-ve-varsayimlar')">{{ m.backToAssumptions }} <span aria-hidden="true">←</span></a><a :href="BASE" class="atlas-primary">{{ m.toExperiment }} <span aria-hidden="true">→</span></a></div>
  </main>
</template>

<style scoped>
.atlas-page{padding-bottom:64px;outline:none}.atlas-intro{display:flex;justify-content:space-between;align-items:flex-start;gap:30px;padding:51px 0 31px}.atlas-eyebrow{font:10px/1.8 var(--mono,monospace);letter-spacing:1.2px;color:var(--theme-muted, #5a6b55)}.atlas-intro h1{font:400 59px/1.13 var(--serif,Georgia,serif);letter-spacing:-1.8px;margin:18px 0 22px;max-width:780px}.atlas-intro h1 em{color:var(--theme-muted, #476f5b)}.atlas-summary{font-size:17px;line-height:1.9;max-width:760px}.atlas-meta{font-size:12px;line-height:1.8;color:var(--theme-muted, #5d6a57);margin-top:17px}.atlas-reset{background:var(--theme-surface-soft, #eef2e5);border:1px solid var(--theme-border, #c5d0ba);border-radius:5px;min-height:44px;padding:12px 15px;font-size:12px;line-height:1.8;color:var(--theme-muted, #4e6844);margin-top:22px;flex:none}.atlas-boundary{border-left:3px solid #7f9871;background:var(--theme-surface-soft, #eaf0e1);padding:17px 21px;font-size:13px;line-height:1.9}.atlas-boundary strong{font-weight:500}.atlas-boundary p{margin-top:6px}.atlas-navigation{display:flex;gap:10px;flex-wrap:wrap;margin:27px 0 31px}.atlas-navigation a{border:1px solid var(--theme-border, #cbd4c0);border-radius:5px;font-size:11px;line-height:1.8;padding:11px 14px;min-height:44px;background:var(--theme-surface, #f8f9ef)}.atlas-navigation a:hover{background:var(--theme-surface-soft, #eaf0e0)}.atlas-section{border-top:1px solid var(--theme-border, #daddd2);padding:35px 0 39px;scroll-margin-top:25px;outline:none}.atlas-section h2{font:400 31px/1.4 var(--serif,Georgia,serif);letter-spacing:-.6px;margin:12px 0 20px}.atlas-paragraph{font-size:14px;line-height:2;color:var(--theme-muted, #4c634b);max-width:920px;margin:16px 0}.atlas-workspace{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:24px;margin-top:28px;align-items:start}.atlas-controls,.atlas-record{border:1px solid var(--theme-border, #cbd5bf);border-radius:8px;padding:24px;min-width:0;background:var(--theme-surface, #fafbf